import{_ as l,l as i,o as e,c as o,v as t,p as n,x as r,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"无线上的 TCP","description":"","frontmatter":{"title":"无线上的 TCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-wireless.md","filePath":"cs/tcp-wireless.md","lastUpdated":1789023840000}'),E={name:"cs/tcp-wireless.md"};function P(C,a,h,T,A,_){const s=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="无线上的-tcp" tabindex="-1">无线上的 TCP <a class="header-anchor" href="#无线上的-tcp" aria-label="Permalink to &quot;无线上的 TCP&quot;">​</a></h1><div class="epigraph"><p>空口误码与切换造成的丢包不是管道满；TCP 若当拥塞减窗，就把完好的 $C$ 浪费掉。</p><footer>—— 据 RFC 3481 2.5G/3G 上的 TCP；Balakrishnan et al. 无线 TCP 综述整理</footer></div><p><a href="/cs/satellite-latency">卫星</a> 已给误码≠拥塞。<a href="/cs/wifi-frames-ofdm">802.11 ACK</a> 做链路重传。<a href="/cs/delay-based-cc">上一课</a> 的延迟信号也会被调度抖动污染。缺口是<strong>蜂窝/Wi‑Fi 上的 TCP 行为</strong>：ELN、PEPs、链路 ARQ 与 RTO。本课结束新传输课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无线丢：衰落、碰撞、切换。链路 ARQ 已努力，仍可能超时。TCP 看到洞就 MD 或 RTO。对策分层：更好的链路 FEC/ARQ（PHY 课）、显式失错通知（少见）、冻结窗口在切换时、PEP 拆连接（破坏端到端）、BBR/延迟 CC 少抽空、QUIC 快速探测。5G URLLC 走专切片，不靠修 TCP。</p><p>不要把「无线 TCP」写成换一个 cc 算法名就结束。</p><p><span class="marginnote">RFC 3481。中间 PEP 有争议（Saltzer）。本课列机制，不推销拆连接。</span></p><h3 id="空口丢-管道满" tabindex="-1">空口丢≠管道满 <a class="header-anchor" href="#空口丢-管道满" aria-label="Permalink to &quot;空口丢≠管道满&quot;">​</a></h3><p>链路 ARQ 会掩盖或推迟。假 MD 浪费 \\(C\\)。PEP 破端到端。先问链路再改 CC。URLLC 走切片不靠修 TCP。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：拥塞丢 vs 无线丢。画：空口丢 → 假 MD → 吞吐低于 \\(C\\)。与 MPTCP：坏口切子流。与 RoCE：无线一般不跑无损 RDMA。</p>',11)),(e(),n(d,null,{default:r(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIRE%5B%22%E6%97%A0%E7%BA%BF%E8%AF%AF%E7%A0%81%22%5D%20--%3E%20HOLE%5B%22TCP%20%E8%A7%81%E6%B4%9E%22%5D%0A%20%20HOLE%20--%3E%20MD%5B%22%E8%AF%AF%E5%BD%93%E6%8B%A5%E5%A1%9E%22%5D%0A%20%20ARQ%5B%22%E9%93%BE%E8%B7%AF%E9%87%8D%E4%BC%A0%22%5D%20--%3E%20MASK%5B%22%E6%8E%A9%E7%9B%96%E6%88%96%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20MASK%20--%3E%20RTO%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%E8%B6%85%E6%97%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓冲膨胀在 LTE 基站很重，交互差。AQM 在基站有帮助。窗口缩放仍要，BDP 随无线 \\(C\\) 变。MSS 小一点抗误码重传代价，与容量摊销权衡。抓包看到的 RTT 含调度，不是传播。</p><p>端到端：应用 FEC（实时后课）比 PEP 更符合 Saltzer。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Snoop TCP 的全部代理状态。HTTP/1.1 持久连接是下一单元第一课。后课默认：无线丢包要先问链路，再问 CC。</p><p>把 RTO 下限盲目降到微秒会在公网误触发。</p><p>上一课留下的缺口在本课收口；「无线上的 TCP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/http11-persistent-chunked">HTTP/1.1 持久连接与分块</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无线丢失≠瓶颈满。</li><li>链路 ARQ、谨慎 CC、多径是配套。</li><li>PEP 换性能、破端到端。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3481；无线 TCP 文献。</li></ul>',10))])}const m=l(E,[["render",P]]);export{f as __pageData,m as default};
